insert into wall_of_faith_years (year, theme) values
  (2023, 'Made New to Make New'),
  (2024, 'Walking Toward the Call, Calling All Who Walk'),
  (2025, 'Made for More'),
  (2026, 'Be · Ready · Be Ready');
insert into wall_of_faith_events (slug, year, sort_date, date_label, title, description, milestone, significance, image_url, youtube_url, needs_review) values
  ('2023-opening-prayer', 2023, '2022-12-01', 'Dec 2022 – May 14, 2023', 'Opening Prayer', 'New Seoul Church was prepared with ten members and the prayers of many people.', 'Prayer', 'Remembering that the church began in dependence on God and recognizing the vital role of intercessory prayer in building His community.', null, null, false),
  ('2023-commission-service', 2023, '2023-05-14', 'May 14, 2023', 'Commission Service', 'NSC began as a community to influence Seoul through discipleship and radical obedience, with a glorious worship service.', null, 'Celebrating God’s grace in establishing NSC and embracing His calling and mission together as a church.', null, null, false),
  ('2023-summer-night', 2023, '2023-07-01', 'July 2023', 'Summer Night', 'NSC held a Summer Night for fellowship and outreach, enjoying a fun and meaningful time together through various activities like board games.', null, 'Nurturing friendship and a sense of belonging in Christ through shared joy and fellowship.', null, null, false),
  ('2023-forerunner-retreat', 2023, '2023-08-10', 'Aug 10–12, 2023', 'Forerunner Retreat', 'NSC''s first retreat — a time of prayer to become servants who lead with initiative and faith. Especially during the final hike up Yongmunsan, we came to deeply understand the meaning of radical obedience.', 'Mt. Yongmun', 'Preparing hearts and lives to serve like Jesus and growing in dependence on God for the ministry entrusted to us.', null, null, false),
  ('2023-fall-festival', 2023, '2023-09-17', 'Sep 17, 2023', 'Fall Festival', 'Fall Festival began in 2023 to give international people a joyful space for fellowship. NSC continues to offer similar outreach ministries in the spring or fall season.', null, 'Expressing God’s love through hospitality, warmly welcoming newcomers and sharing food and joy together.', null, null, false),
  ('2023-chuseok-experience', 2023, '2023-09-30', 'Sep 30, 2023', 'Chuseok Experience', 'For foreigners unfamiliar with the Korean holiday Chuseok, NSC provided a time to experience various aspects of Korean culture and enjoy fellowship together.', null, 'Extending family-like hospitality to international students and practicing love for our neighbors across cultural differences.', null, null, false),
  ('2023-dt-phase1-cohort1', 2023, '2023-10-01', 'Oct 2023', 'DT Phase 1, Cohort 1', 'From October, NSC carried out a six-month discipleship training program focused on the core value of Radical Obedience.', null, null, null, null, false),
  ('2023-thanksgiving', 2023, '2023-11-25', 'Nov 25, 2023', 'Thanksgiving', 'Thanksgiving is like a festival for NSC. It was a time when all members gathered for fellowship and shared gratitude for the past year.', null, 'Giving thanks for God’s provision and celebrating our unity as one body in Christ through the sharing of cultures and food.', null, null, false),
  ('2023-christmas', 2023, '2023-12-25', 'Dec 25, 2023', 'Christmas', 'We spent time reflecting on the shepherds who awaited Jesus and meditated on the true meaning of Christmas.', 'Family worship', 'Celebrating the love of Jesus, who came to dwell among us, and worshiping together as one family in Christ.', null, null, false),
  ('2023-new-year-service', 2023, '2024-01-01', 'Jan 1, 2024', 'New Year Service', 'As we closed the year, we spent time worshipping together, holding expectations and vision for 2024.', null, 'Thanking God for His guidance throughout the past year and entrusting the coming year to His faithfulness.', null, null, false),
  ('2024-new-year-prayer-walk', 2024, '2024-01-02', 'Jan 2–5, 2024', 'New Year Prayer Walk', 'NSC began the new year with a Prayer Walk, choosing to walk forward into the world with prayer and hope. As we walked through Seoul, we sought to live out our vision — Walking Toward the Call, Calling All Who Walk — trusting God to lead every step of our journey.', null, 'Entrusting our steps in the new year to God and interceding for the city with a heart shaped by His love.', null, null, false),
  ('2024-life-group-olympic', 2024, '2024-01-28', 'Jan 28, 2024', 'Life Group Olympic', 'Life Groups are one of the core communities at NSC, where we share life together and grow in faith. Once a year, all Life Groups come together for the Life Group Olympics — a joyful time of connection, teamwork, and celebration.', null, 'Experiencing the joy and unity of being one body as members with different gifts cooperate and encourage one another.', null, null, false),
  ('2024-membership-class', 2024, '2024-02-04', 'Feb 4 & 18, 2024', 'Membership Class', 'To build NSC''s covenant family, we launched our Membership Class. Through this time, members are able to gain a deeper understanding of our church''s vision, values, and philosophy.', null, 'Sharing in the church’s vision and faith, putting down roots in the community, and committing to love and serve one another faithfully.', null, null, false),
  ('2024-freedom-prayer-walk', 2024, '2024-03-01', 'Mar 1, 2024', 'Freedom Prayer Walk', 'On Korea''s Independence Movement Day, NSC walked through Northern part of Seoul, praying for the spiritual freedom of this nation. Together, we completed the journey in unity and faith.', null, 'Lifting the nation and city to God and praying for His peace, restoration, and true freedom to take root in this land.', null, null, false),
  ('2024-passion-week-prayer', 2024, '2024-03-25', 'Mar 25–28, 2024', 'Passion Week Early Morning Prayer', 'During Holy Week, NSC held an Early Morning Prayer, reflecting on the suffering of Christ and spending time in prayer together. We were reminded of Jesus'' love, sacrifice, and mercy, and deeply reflected on the grace given to the undeserving.', null, 'Offering the first moments of the day to God, reflecting on Jesus’ love and sacrifice on the cross, and responding in repentance and prayer.', null, null, false),
  ('2024-good-friday', 2024, '2024-03-29', 'Mar 29, 2024', 'Good Friday Service', 'On Good Friday, NSC held a foot-washing service as a reminder to become servants like Christ. Through this time, we were shaped as Christians who serve others and reflect Jesus'' love in the world.', 'Washing feet', 'Learning from Jesus’ humility and service through foot washing, and remembering His saving sacrifice through the sharing of a Passover meal.', null, null, false),
  ('2024-easter-sunday', 2024, '2024-03-31', 'Mar 31, 2024', 'Easter Sunday', 'On Easter Sunday, NSC held 360 Worship for the first time. Through this time, we were able to rejoice as worshipers — not just the worship leaders, but solely Christ-centered worship, united as one church.', 'Hope hunt', 'Celebrating Jesus’ resurrection and the joy of new life, and learning to see our everyday lives and city through the hope of the risen Christ.', null, null, false),
  ('2024-dure-fasting-retreat', 2024, '2024-04-10', 'Apr 10–13, 2024', 'DURE (두레) Fasting Retreat', 'Fasting prayer helps awaken our souls. During the Dure Retreat, we experienced a time of emptying ourselves physically, while being spiritually filled and renewed.', 'Clicker', null, null, null, false),
  ('2024-breakthrough-retreat', 2024, '2024-05-10', 'May 10–12, 2024', 'Breakthrough Retreat', 'At the Breakthrough Retreat, NSC had seven-hour worship, offering glory to the Lord alone. It was a time of being led beyond our limits, learning to give God our very best in wholehearted worship.', '7hrs worship', 'Reflecting on God’s faithfulness in leading the church, sharing rest and fellowship, and renewing our calling as a community.', null, null, false),
  ('2024-dt-phase2-cohort1', 2024, '2024-05-12', 'Early 2024', 'DT Phase 2, Cohort 1', 'DT Phase 2 started in the beginning of 2024. Through this process, participants grew in their understanding of Scripture and doctrine while learning the leadership of serving others.', null, null, null, null, false),
  ('2024-sports-monster-bungae', 2024, '2024-05-15', 'May 15, 2024', 'Sports Monster 1st Bungae (번개) Fellowship', 'NSC is not a community that gathers only on Sundays. Through spontaneous gatherings called Bungae Fellowship, we grow closer as a family and build deeper relationships together.', null, null, null, null, false),
  ('2024-mission-fair', 2024, '2024-06-09', 'Jun 9, 2024', 'Mission Fair', 'Once a year, through the Mission Fair, we come together as an international church to share our cultures, introduce our home countries, and lift up prayer requests for each nation.', null, null, null, null, false),
  ('2024-palawan-mission', 2024, '2024-07-22', 'Jul 22–27, 2024', 'Palawan Mission', 'The Palawan Mission was NSC''s first overseas mission trip. After intensive mission training, our members went to serve the people of the Philippines and returned with hearts transformed through ministry.', null, 'Partnering with local ministry workers to share the gospel in word and deed and participating in God’s love for all nations across cultures and borders.', null, null, false),
  ('2024-freedom-prayer-walk-aug', 2024, '2024-08-14', 'Aug 14–15, 2024', 'Freedom Prayer Walk', 'On August 15, NSC once again walked through Seoul — the southern part of the city this time. As we visited key places throughout the city, we worshipped and prayed, dreaming of revival for Korea.', null, null, null, null, false),
  ('2024-haven-staff-retreat', 2024, '2024-08-23', 'Aug 23–24, 2024', 'Haven Staff Retreat', 'The servants of NSC always strive to give "Better Than Our Best" in their service. To encourage and strengthen our core staff as co-laborers, we held the Haven Staff Retreat.', 'Camping', null, null, null, false),
  ('2024-christmas-play', 2024, '2024-12-25', 'Dec 25, 2024', 'Christmas', 'To celebrate Christmas, NSC joyfully celebrated the birth of Jesus through a creative musical performance.', 'Christmas play', null, null, null, false),
  ('2024-new-year-service', 2024, '2024-12-31', 'Dec 31, 2024', 'New Year Service', 'The final day of 2024 was concluded as we gathered together in worship, watching the top 10 worship songs and the top 10 events of the year video, and sharing joy and gratitude.', null, null, null, null, false),
  ('2025-glory-retreat', 2025, '2025-02-07', 'Feb 7–9, 2025', 'Glory Retreat', 'At the Glory Retreat, NSC reflected deeply on the 2025 vision, "Made for More." Through activities like ice baths and workouts, we grew closer and stronger together as one community.', 'Ice bath', null, null, null, false),
  ('2025-nsb-begins', 2025, '2025-03-13', 'Mar 13, 2025', 'NSB (New Seoul Basketball) Begins', 'NSB is a basketball outreach ministry that welcomes everyone, regardless of faith, creating a space of connection and community.', null, null, null, null, false),
  ('2025-town-hall-meeting', 2025, '2025-04-06', 'Apr 6, 2025', 'Town Hall Meeting', 'The Town Hall Meeting reflected our heart to openly share the church''s direction and operate with transparency.', null, null, null, null, false),
  ('2025-passion-week', 2025, '2025-04-14', 'Apr 14–17, 2025', 'Passion Week', 'Throughout Passion Week, NSC gathered for early morning prayer, meditating on the depth of Christ''s suffering through various messages and worship leaders.', null, null, null, null, false),
  ('2025-easter-sunday', 2025, '2025-04-20', 'Apr 20, 2025', 'Easter Sunday', 'For Easter, a drama was prepared following the Christmas performance. Every detail — from the stage setting to the message — was thoughtfully prepared, and the sermon, shared through Peter''s perspective, helped us deeply reflect on the true meaning of Christ''s resurrection.', 'Easter play', null, null, null, false),
  ('2025-readycall', 2025, '2025-05-06', 'May 6, 2025', 'ReadyCall', 'ReadyCall is the largest Christian fair in Korea. NSC participated by preparing a global booth, sharing prayer requests from various nations, and serving the event through prayer.', null, null, null, null, false),
  ('2025-2nd-year-anniversary', 2025, '2025-05-11', 'May 11, 2025', '2nd Year Anniversary', 'In celebration of the church''s 2nd anniversary, additional booths representing different nations were prepared, allowing us to share cultures, stories, and prayer requests.', null, null, null, null, false),
  ('2025-pray-4-korea', 2025, '2025-06-04', 'Jun 4–8, 2025', 'Pray 4 Korea', 'Pray4Korea was a journey from Seoul to Busan by bicycle, filled with worship and prayer. Over four days, we poured out our strength and prayed that all of us would choose prayer and worship, standing as true worshipers before the Lord.', null, null, null, null, false),
  ('2025-bungae-fellowship', 2025, '2025-06-20', '2025 (ongoing)', 'Bungae Fellowship', 'NSC''s Bungae Fellowship continues in 2025 and will carry on in the years to come.', null, null, null, null, false),
  ('2025-indonesia-mission', 2025, '2025-06-30', 'Jun 30 – Jul 7, 2025', 'Indonesia Mission', 'Through the Indonesia mission, we visited churches in the Red Zone and partnered with local congregations, experiencing the beauty of the universal Church beyond nations and cultures.', 'Basketball', null, null, null, false),
  ('2025-korea-mission', 2025, '2025-07-28', 'Jul 28 – Aug 1, 2025', 'Korea Mission', 'NSC visited Seondeok Orphanage in Jeollabuk-do to spend time with the children and hold them in prayer. This became the starting point of a monthly outreach to continually serve and support the children.', 'Sunduk Orphanage ministry', null, null, null, false),
  ('2025-nsk-vbs', 2025, '2025-08-09', 'Aug 9–10, 2025', 'NSK VBS (Vacation Bible School)', 'NSK (New Seoul Kids) prepared for their first VBS by reaching out to the local community with flyers. Under the theme "Jesus is the Light," the children enjoyed a joyful time of dancing, worship, and celebrating together.', 'Light', null, null, null, false),
  ('2025-yongmun-mountain', 2025, '2025-08-15', 'Aug 15, 2025', 'Yongmun Mountain', 'After two years, we returned to Yongmunsan — where we had not been able to reach the summit during the 2023 Forerunner Retreat. This time, we completed the climb, learning the importance of perseverance and being reminded to never give up and to press on toward victory in both life and faith.', null, null, null, null, false),
  ('2025-journey-retreat', 2025, '2025-10-09', 'Oct 9–12, 2025', 'Journey Retreat', 'Through The Pilgrim''s Progress, the Journey Retreat led us to reflect on the temptations, endurance, and victory found in our walk of faith. As we looked toward the Celestial City, we renewed our commitment to walk this journey together.', 'Pilgrim’s progress', null, null, null, false),
  ('2025-christmas-project', 2025, '2025-12-01', 'December 2025', 'Christmas Project', 'Throughout the Christmas season, NSC reflected on the birth of Jesus through the theme "Light in the Darkness," expressed in different ways each week. Through our action plan for the children of Seondeok Orphanage, we were reminded of our calling to shine Christ''s light in the world.', 'Guardians system for Sunduk Orphanage kids', null, null, null, false),
  ('2025-christmas-film', 2025, '2025-12-25', 'Dec 25, 2025', 'Christmas', 'In 2025, NSC created a film for Christmas. Through a lighthearted yet meaningful story, we reflected deeply on the true joy found in Jesus.', 'Christmas film', null, null, null, false),
  ('2024-discipleship-sunday', 2024, '2024-03-10', 'Mar 10, 2024', 'Discipleship Sunday', 'A Sunday service centered on discipleship and what it means to follow Jesus together.', null, null, null, null, true),
  ('2024-dt-phase-1-cohort-2', 2024, '2024-01-01', '2024', 'DT Phase 1, Cohort 2', 'The second cohort began Phase 1 of NSC''s Discipleship Training.', null, null, null, null, true),
  ('2024-new-glow', 2024, '2024-10-26', 'Oct 26, 2024', 'New Glow', 'New Glow brought the young people of NSC together for a gathering of their own.', 'Young people’s gathering', null, null, null, true),
  ('2025-dt-phase-1-cohort-3', 2025, '2025-01-01', '2025', 'DT Phase 1, Cohort 3', 'The third cohort began Phase 1 of NSC''s Discipleship Training.', null, null, null, null, true),
  ('2025-baptism', 2025, '2025-04-06', 'Apr 6, 2025', 'Baptism', 'Members were baptized and publicly declared their faith in Jesus before the church.', null, null, null, null, true);
